import{f as a,o,c as e,a2 as n}from"./chunks/framework.BUDOXiIz.js";const m=JSON.parse('{"title":"CoopApps — Del comparativo funcional a la presentación (marketing, gerencia y técnico)","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/comparativo-funcional-procoop-vs-coopapps-para-presentacion.md","filePath":"presentacion-stakeholders/comparativo-funcional-procoop-vs-coopapps-para-presentacion.md","lastUpdated":null}'),r={name:"presentacion-stakeholders/comparativo-funcional-procoop-vs-coopapps-para-presentacion.md"};function s(d,t,i,c,l,p){return o(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="coopapps-—-del-comparativo-funcional-a-la-presentacion-marketing-gerencia-y-tecnico" tabindex="-1">CoopApps — Del comparativo funcional a la presentación (marketing, gerencia y técnico) <a class="header-anchor" href="#coopapps-—-del-comparativo-funcional-a-la-presentacion-marketing-gerencia-y-tecnico" aria-label="Permalink to &quot;CoopApps — Del comparativo funcional a la presentación (marketing, gerencia y técnico)&quot;">​</a></h1><p>Guía para <strong>armar diapositivas y discurso</strong> a partir del comparativo exhaustivo, <strong>sin perder rigor</strong>. Cada bloque tiene tres capas:</p><table tabindex="0"><thead><tr><th>Capa</th><th>Quién la usa</th><th>Qué contiene</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td>Marketing, diseño, comunicación</td><td>Título de slide, idea en una frase, texto visible sugerido (máx. 15 palabras por viñeta)</td></tr><tr><td><strong>Gerencia</strong></td><td>Presidente, gerentes, consejo</td><td>Riesgo/beneficio, decisión implícita, “qué preguntar”</td></tr><tr><td><strong>Respaldo</strong></td><td>Sistemas, facturación, contador, legal</td><td>Números verificables, trazabilidad al comparativo y a la especificación</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Fecha</td><td>19-11-2026</td></tr><tr><td>Documento fuente (anexo técnico)</td><td><a href="./comparativo-funcional-procoop-vs-coopapps"><code>comparativo-funcional-procoop-vs-coopapps.md</code></a> v1.1</td></tr><tr><td>Documentos hermanos</td><td><code>dolores-procoop-antes-y-despues.md</code>, <code>documento-base-presentacion.md</code>, <code>lo-esencial-para-imagenes.md</code></td></tr><tr><td><strong>Comparativo exhaustivo (muchas slides)</strong></td><td><a href="./comparativo-funcional-imagenes-exhaustivas-hoy-vs-coopapps"><code>comparativo-funcional-imagenes-exhaustivas-hoy-vs-coopapps.md</code></a> — códigos <strong>IMG-V00…V35</strong>, tabla Hoy | Con CoopApps por función</td></tr><tr><td><strong>Megaspec + imágenes funcionales</strong></td><td><a href="./comparativo-funcional-megaspec-unificado"><code>comparativo-funcional-megaspec-unificado.md</code></a> + <a href="./comparativo-funcional-imagenes-F-PROMPT-CLAUDE"><code>comparativo-funcional-imagenes-F-PROMPT-CLAUDE.md</code></a> (<strong>IMG-F</strong>, sin códigos M/T en tabla)</td></tr><tr><td><strong>Deck marketing “lo nuevo”</strong></td><td><a href="./lo-nuevo-coopapps-vs-procoop-PROMPT-COMPLETO-CLAUDE"><code>lo-nuevo-coopapps-vs-procoop-PROMPT-COMPLETO-CLAUDE.md</code></a> — <strong>IMG-N00…N23</strong></td></tr><tr><td>Regla</td><td><strong>No inventar números ni promesas.</strong> Si un dato no está en el comparativo o en el documento base, dejarlo en ámbar “a validar con el equipo”.</td></tr></tbody></table><hr><h2 id="_0-como-usar-este-documento-marketing-y-diseno" tabindex="-1">0. Cómo usar este documento (marketing y diseño) <a class="header-anchor" href="#_0-como-usar-este-documento-marketing-y-diseno" aria-label="Permalink to &quot;0. Cómo usar este documento (marketing y diseño)&quot;">​</a></h2><h3 id="_0-1-flujo-recomendado" tabindex="-1">0.1 Flujo recomendado <a class="header-anchor" href="#_0-1-flujo-recomendado" aria-label="Permalink to &quot;0.1 Flujo recomendado&quot;">​</a></h3><ol><li>Elegir <strong>una versión</strong> de la presentación (§1: corta / estándar / completa).</li><li>Por cada slide, copiar la capa <strong>Público</strong> al PowerPoint; pegar <strong>Gerencia</strong> en notas del presentador; guardar <strong>Respaldo</strong> en anexo impreso o PDF de respaldo.</li><li>Si alguien pide prueba (“¿dónde está escrito?”), abrir el comparativo en la sección citada en <strong>Respaldo</strong>.</li><li>Para imágenes con IA: usar el prompt maestro §0.2 y los códigos <strong>IMG-C01…</strong> de §2.</li></ol><h3 id="_0-2-prompt-maestro-para-claude-copiar-y-pegar" tabindex="-1">0.2 Prompt maestro para Claude (copiar y pegar) <a class="header-anchor" href="#_0-2-prompt-maestro-para-claude-copiar-y-pegar" aria-label="Permalink to &quot;0.2 Prompt maestro para Claude (copiar y pegar)&quot;">​</a></h3><p>Adjuntá en el chat, en este orden:</p><ol><li><code>comparativo-funcional-procoop-vs-coopapps-para-presentacion.md</code> (este archivo)</li><li><code>comparativo-funcional-procoop-vs-coopapps.md</code> (anexo técnico)</li><li>Opcional para bloque dolores / guion completo: <code>dolores-procoop-antes-y-despues.md</code>, <code>documento-base-presentacion.md</code></li></ol><p>Luego pegá el bloque siguiente.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sos mi diseñador de presentación ejecutiva para una reunión con directivos de cooperativas de servicios públicos de Argentina. El producto es CoopApps (SaaS en la nube); el sistema de referencia es ProCoop (escritorio).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Te adjunto la guía de presentación del comparativo funcional y el comparativo v1.1. Son la única fuente de textos y números.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MENSAJE CENTRAL (no desviarte):</span></span>
<span class="line"><span>&quot;ProCoop es respetable y profundo. CoopApps cubre el mismo negocio (119 de 120 funciones del menú relevado), mejora lo que duele (nube, portal en vivo, seguridad, migración por etapas) y suma experiencia digital con la marca de cada cooperativa — sin apagar la operación un viernes.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REGLAS OBLIGATORIAS</span></span>
<span class="line"><span>1. Usá SOLO datos de los archivos adjuntos. No inventes cifras, módulos, promesas ni nombres de cooperativas reales. Si falta un dato, dejá un hueco con &quot;—&quot; y avisame.</span></span>
<span class="line"><span>2. Español de Argentina, formal y claro. Sin adjetivos vacíos: nada de &quot;revolucionario&quot;, &quot;disruptivo&quot;, &quot;líder&quot;, &quot;el mejor&quot;.</span></span>
<span class="line"><span>3. ProCoop: siempre con respeto (&quot;sistema de referencia&quot;, &quot;lo que usan hoy&quot;). El &quot;antes&quot; en grises apagados; nunca rojo chillón para atacar al competidor.</span></span>
<span class="line"><span>4. CoopApps / lo nuevo: acento verde cooperativo #2E7D32. Ámbar #B7791F solo para API completa en ola O11 o temas &quot;a decidir&quot;. Rojo #B91C1C solo si el documento cita un defecto de seguridad comprobado (no inventar).</span></span>
<span class="line"><span>5. Paleta general: títulos #2F343A, texto secundario #6B7280, tarjetas #E5E7EB, fondo #FFFFFF.</span></span>
<span class="line"><span>6. Formato: cada diapositiva como artefacto HTML autocontenido con SVG (o canvas) 1920×1080 px, 16:9, listo para capturar o exportar a PNG. NO uses el generador de imágenes para slides con números o tablas (deforman cifras).</span></span>
<span class="line"><span>7. Tipografía sans serif (Inter o similar). Título 56–72 px; viñetas ≥20 px; mucho aire; máximo 4 viñetas por slide.</span></span>
<span class="line"><span>8. Íconos de línea simples. Estilo consultora sobria: sin robots, cerebros, cohetes ni personas caricaturescas.</span></span>
<span class="line"><span>9. Datos ficticios: &quot;Cooperativa A&quot;, &quot;Socio de ejemplo&quot;, importes redondos. Nunca DNI, CUIT ni direcciones reales.</span></span>
<span class="line"><span>10. Estados: nunca solo color; siempre texto o ícono + color.</span></span>
<span class="line"><span>11. Comparativos &quot;Hoy / Con CoopApps&quot;: columna izquierda &quot;Hoy&quot; (gris), derecha &quot;Con CoopApps&quot; (verde suave), salvo que el documento indique otro layout.</span></span>
<span class="line"><span>12. Después de CADA imagen, en el chat (no en el SVG), entregá tres bloques:</span></span>
<span class="line"><span>    - Público (lo que va en la slide)</span></span>
<span class="line"><span>    - Gerencia (notas del orador, 3–5 líneas)</span></span>
<span class="line"><span>    - Respaldo (sección del comparativo o guía §2)</span></span>
<span class="line"><span>    - Lista de números usados y su sección fuente</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CÓDIGOS DE ESTE BLOQUE (prioridad reunión comparativo)</span></span>
<span class="line"><span>Genero las diapositivas bajo pedido con estos códigos, tomando textos de la §2 de la guía adjunta:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C01 Portada comparativo</span></span>
<span class="line"><span>IMG-C02 Respeto por ProCoop</span></span>
<span class="line"><span>IMG-C03 Número ancla 119/120 funciones del menú</span></span>
<span class="line"><span>IMG-C04 Ocho aplicaciones, un solo dato</span></span>
<span class="line"><span>IMG-C05 Socio: misma información que caja</span></span>
<span class="line"><span>IMG-C06 Siete dolores (resumen; detalle visual en IMG-D03 si adjunto dolores)</span></span>
<span class="line"><span>IMG-C07 Facturación y cobranza con control</span></span>
<span class="line"><span>IMG-C08 Técnica y campo, flujo integral</span></span>
<span class="line"><span>IMG-C09 Lo nuevo más allá de reemplazar pantallas</span></span>
<span class="line"><span>IMG-C10 Diecisiete familias de servicio</span></span>
<span class="line"><span>IMG-C11 Migración: 12 olas O0–O11, sin big bang</span></span>
<span class="line"><span>IMG-C12 Checklist consejo (6 ítems de la guía §12 del comparativo)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Opcionales si pido versión estándar/completa: IMG-C13 a IMG-C24 (misma guía §2).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GUION UNIFICADO (si pido &quot;deck completa&quot;)</span></span>
<span class="line"><span>Seguí el orden §0.5 de la guía: IMG-C encajan en pasos 5, 8–12, 14, 17, 22; el resto son IMG-01…25, IMG-D, IMG-E, IMG-A según tabla §0.6 — no dupliques el mismo número en dos slides distintas.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PROHIBIDO DECIR EN TEXTO VISIBLE</span></span>
<span class="line"><span>- &quot;Mismas pantallas&quot; (decir: misma función de negocio)</span></span>
<span class="line"><span>- &quot;API desde el día 1&quot; (decir: exportaciones ya; API documentada planificada O11, salvo ámbar)</span></span>
<span class="line"><span>- &quot;Tiempo real al milisegundo&quot;</span></span>
<span class="line"><span>- &quot;Sin ProCoop&quot; / &quot;reemplazo total inmediato&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PLANTILLA POR PEDIDO</span></span>
<span class="line"><span>Cuando yo escriba &quot;Generá IMG-C03&quot;, hacé:</span></span>
<span class="line"><span>1. Leer §2 IMG-C03 de la guía (capas Público, Gerencia, Respaldo).</span></span>
<span class="line"><span>2. Crear HTML/SVG 1920×1080 con el contenido Público.</span></span>
<span class="line"><span>3. Responder con Gerencia, Respaldo y verificación de números.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Confirmá que leíste los adjuntos y esperá mi primer código (sugerencia: empezar por IMG-C02, luego IMG-C03).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br></div></div><h3 id="_0-3-glosario-en-lenguaje-llano-para-no-errar-el-discurso" tabindex="-1">0.3 Glosario en lenguaje llano (para no errar el discurso) <a class="header-anchor" href="#_0-3-glosario-en-lenguaje-llano-para-no-errar-el-discurso" aria-label="Permalink to &quot;0.3 Glosario en lenguaje llano (para no errar el discurso)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Si en marketing decís…</th><th>Significa funcionalmente…</th><th>No decir (impreciso)</th></tr></thead><tbody><tr><td>“La app del socio con la marca de la cooperativa”</td><td>M19 portal/PWA + T03 marca por canal</td><td>“App nueva mágica”</td></tr><tr><td>“Misma información en oficina y en el celular”</td><td>Sin réplica MySQL CoopOnline; un solo dato</td><td>“Tiempo real milisegundo”</td></tr><tr><td>“Todo el menú cubierto”</td><td>119/120 funciones PC con destino</td><td>“Mismas pantallas”</td></tr><tr><td>“Migración por etapas”</td><td>Olas O0–O11; paralelo factura a factura</td><td>“Cambio un fin de semana”</td></tr><tr><td>“Los datos son de la cooperativa”</td><td>Exportación tenant + reportes; API O11</td><td>“API desde el día 1” (salvo decisión de adelanto)</td></tr><tr><td>“Más control”</td><td>Reglas, auditoría, aprobaciones, lotes</td><td>“Más botones”</td></tr></tbody></table><h3 id="_0-4-familias-de-codigos-una-sola-reunion-un-solo-guion" tabindex="-1">0.4 Familias de códigos (una sola reunión, un solo guion) <a class="header-anchor" href="#_0-4-familias-de-codigos-una-sola-reunion-un-solo-guion" aria-label="Permalink to &quot;0.4 Familias de códigos (una sola reunión, un solo guion)&quot;">​</a></h3><p>Todos los documentos de <code>presentacion-stakeholders</code> usan prefijos distintos. <strong>No se mezclan en la misma slide</strong> salvo que la tabla de cruces lo indique.</p><table tabindex="0"><thead><tr><th>Prefijo</th><th>Documento</th><th>Rol en la reunión</th></tr></thead><tbody><tr><td><strong>IMG-01…25</strong></td><td><code>documento-base-presentacion.md</code></td><td>Hilo principal: relevamiento, especificación, arquitectura, olas, propuesta</td></tr><tr><td><strong>IMG-D01…14</strong></td><td><code>dolores-procoop-antes-y-despues.md</code></td><td>Bloque emocional y honesto “hoy → CoopApps” (reemplaza IMG-08)</td></tr><tr><td><strong>IMG-C01…24</strong></td><td>Este documento</td><td>Bloque <strong>comparativo funcional</strong> ProCoop vs CoopApps (menú, módulos, socio)</td></tr><tr><td><strong>IMG-E01…12</strong></td><td><code>lo-esencial-para-imagenes.md</code></td><td>Refuerzo de <strong>una idea + un número</strong> entre bloques (opcional, no duplicar mensaje)</td></tr><tr><td><strong>IMG-A01…08</strong></td><td><code>alcance-especificacion-modulo-por-modulo.md</code></td><td>Profundizar alcance si preguntan “¿qué trae cada módulo?”</td></tr><tr><td><strong>IMG-F-M*, T*</strong></td><td>Ídem</td><td>Fichas por módulo; <strong>anexo</strong> o reunión técnica larga</td></tr></tbody></table><p><strong>Regla de oro:</strong> el <strong>documento base</strong> lleva la historia del <em>proyecto</em>; <strong>IMG-D</strong> lleva los <em>dolores</em>; <strong>IMG-C</strong> lleva la <em>prueba de cobertura funcional</em> (“no perdemos el menú”). Los tres deben decir lo mismo en los números críticos: <strong>119/120</strong>, <strong>12 olas</strong>, <strong>API en O11</strong>.</p><h3 id="_0-5-guion-unificado-recomendado-reunion-ejecutiva-con-comparativo" tabindex="-1">0.5 Guion unificado recomendado (reunión ejecutiva con comparativo) <a class="header-anchor" href="#_0-5-guion-unificado-recomendado-reunion-ejecutiva-con-comparativo" aria-label="Permalink to &quot;0.5 Guion unificado recomendado (reunión ejecutiva con comparativo)&quot;">​</a></h3><p>Orden para <strong>una sola presentación</strong> de ~50–60 minutos, sin saltar de narrativa. La columna <strong>Generar</strong> indica qué código pedir a Claude/ChatGPT (puede ser más de una imagen por fila).</p><table tabindex="0"><thead><tr><th>Orden</th><th>Bloque</th><th>Mensaje en voz alta</th><th>Generar (prioridad)</th><th>Notas del presentador</th></tr></thead><tbody><tr><td>1</td><td>Apertura</td><td>“Del relevamiento al plan de construcción.”</td><td>IMG-01</td><td>Documento base §1.1</td></tr><tr><td>2</td><td>Contexto</td><td>“Escuchamos sus prioridades.”</td><td>IMG-02</td><td></td></tr><tr><td>3</td><td>Trabajo hecho</td><td>“Lo que estaba planificado en meses ya está escrito.”</td><td>IMG-03, IMG-E01</td><td>E01 refuerza el contraste tiempo</td></tr><tr><td>4</td><td>Método</td><td>“No solo entrevistas: leímos el sistema.”</td><td>IMG-05, IMG-06</td><td>Iceberg + números ProCoop</td></tr><tr><td>5</td><td>Respeto</td><td>“ProCoop hace mucho; no venimos a restarle.”</td><td><strong>IMG-C02</strong></td><td>Antes del bloque dolores</td></tr><tr><td>6</td><td>Dolores</td><td>“Esto nos dijeron que dolía.”</td><td><strong>IMG-D02</strong>, <strong>IMG-D03</strong></td><td><strong>Sustituye IMG-08</strong></td></tr><tr><td>7</td><td>Antes/después</td><td>“Así cambia en la práctica.”</td><td>IMG-D04 a IMG-D10</td><td>Corta: solo D04, D07, D08, D10</td></tr><tr><td>8</td><td>Cobertura menú</td><td>“Función por función: 119 de 120.”</td><td><strong>IMG-C03</strong></td><td>Número ancla del comparativo</td></tr><tr><td>9</td><td>Socio</td><td>“Misma información que caja.”</td><td><strong>IMG-C05</strong>, IMG-D07, IMG-A06</td><td>Evitar repetir D07 y C05 mismo título</td></tr><tr><td>10</td><td>Operación</td><td>“Facturar y cobrar con control.”</td><td><strong>IMG-C07</strong>, IMG-E05, IMG-18</td><td></td></tr><tr><td>11</td><td>Campo</td><td>“Del turno a la conformidad.”</td><td><strong>IMG-C08</strong>, IMG-D13</td><td></td></tr><tr><td>12</td><td>Amplitud</td><td>“Diecisiete servicios, reglas propias.”</td><td><strong>IMG-C10</strong>, IMG-A02</td><td></td></tr><tr><td>13</td><td>Especificación</td><td>“Está todo escrito y trazado.”</td><td>IMG-09, IMG-10, IMG-11, IMG-12</td><td></td></tr><tr><td>14</td><td>Comparativo módulos</td><td>“De ProCoop a CoopApps, sin huecos.”</td><td><strong>IMG-C04</strong>, IMG-A07</td><td>A07 visual; C04 texto gerencia</td></tr><tr><td>15</td><td>Principios</td><td>“Casos difíciles ya pensados.”</td><td>IMG-A04, IMG-A05, comparativo §10</td><td></td></tr><tr><td>16</td><td>Arquitectura</td><td>“Cómo funciona por dentro.”</td><td>IMG-16, IMG-17</td><td></td></tr><tr><td>17</td><td>Migración</td><td>“Sin apagar un viernes.”</td><td><strong>IMG-C11</strong>, IMG-21, IMG-22</td><td>Mismo mensaje que IMG-22</td></tr><tr><td>18</td><td>Escuchamos</td><td>“43 necesidades del equipo anterior.”</td><td>IMG-13, IMG-14</td><td></td></tr><tr><td>19</td><td>Decisiones</td><td>“Qué falta que decidan ustedes.”</td><td>IMG-19, IMG-20</td><td>API adelantada = ámbar</td></tr><tr><td>20</td><td>Riesgos y plazo</td><td>“Medimos antes de prometer.”</td><td>IMG-23, IMG-24, IMG-E12</td><td></td></tr><tr><td>21</td><td>Cierre dolores</td><td>“Cada dolor trazado a requisito.”</td><td>IMG-D14</td><td></td></tr><tr><td>22</td><td>Cierre comparativo</td><td>“Checklist para el consejo.”</td><td><strong>IMG-C12</strong></td><td>Reparte anexo comparativo PDF</td></tr><tr><td>23</td><td>Propuesta</td><td>“Tres pasos para seguir.”</td><td>IMG-25, IMG-E13 o IMG-L02</td><td><code>como-tomar-la-especificacion</code></td></tr></tbody></table><p><strong>Versión corta (25 min):</strong> filas 1, 3, 5, 6, 8, 9, 17, 22, 23 — resto en anexo.</p><p><strong>Frase única del bloque comparativo (antes de IMG-C03):</strong><br><em>“Ahora la pregunta concreta: ¿perdemos algo del menú que usan hoy? La respuesta está relevada función por función.”</em></p><h3 id="_0-6-tabla-de-cruces-img-c-↔-img-↔-img-d-↔-img-e-↔-img-a" tabindex="-1">0.6 Tabla de cruces (IMG-C ↔ IMG ↔ IMG-D ↔ IMG-E ↔ IMG-A) <a class="header-anchor" href="#_0-6-tabla-de-cruces-img-c-↔-img-↔-img-d-↔-img-e-↔-img-a" aria-label="Permalink to &quot;0.6 Tabla de cruces (IMG-C ↔ IMG ↔ IMG-D ↔ IMG-E ↔ IMG-A)&quot;">​</a></h3><p>Usar para <strong>no duplicar</strong> slides ni contradecir números. Si dos códigos comparten fila, elegir <strong>uno</strong> en la deck y dejar el otro en anexo.</p><table tabindex="0"><thead><tr><th>IMG-C (comparativo)</th><th>Equivalente / complemento</th><th>Dolores IMG-D</th><th>Esencial IMG-E</th><th>Alcance IMG-A</th><th>Sección comparativo</th></tr></thead><tbody><tr><td>C01 Portada comparativo</td><td>IMG-01 (portada general)</td><td>D01 portada bloque</td><td>—</td><td>—</td><td>§1</td></tr><tr><td>C02 Respeto ProCoop</td><td>IMG-05, IMG-06</td><td>D02</td><td>—</td><td>—</td><td>§1.3</td></tr><tr><td>C03 <strong>119/120</strong></td><td><strong>IMG-12</strong> cobertura</td><td>D14 (cierre trazabilidad)</td><td><strong>E04</strong> nada se pierde</td><td><strong>A07</strong> ProCoop→módulos</td><td>§0.3, §3</td></tr><tr><td>C04 Ocho aplicaciones</td><td>IMG-10 mapa</td><td>—</td><td>—</td><td>A01 mapa 30 módulos</td><td>§0.2, §4</td></tr><tr><td>C05 Socio mismo dato</td><td>—</td><td><strong>D07</strong>, <strong>D08</strong></td><td><strong>E09</strong> bolsillo socio</td><td><strong>A06</strong> socio punta a punta</td><td>§2.2, §6.4</td></tr><tr><td>C06 Siete dolores</td><td><s>IMG-08</s> usar D</td><td><strong>D03</strong></td><td>—</td><td>—</td><td>§2 + dolores §2.1</td></tr><tr><td>C07 Facturación/cobranza</td><td>IMG-18 ARCA flujo</td><td>—</td><td><strong>E05</strong> cada peso; <strong>E08</strong> ARCA</td><td>F-M05, F-M07</td><td>§3.4–6, §10</td></tr><tr><td>C08 Técnica/campo</td><td>—</td><td><strong>D13</strong> instalación</td><td>—</td><td>F-M10</td><td>§3.7, §6.1</td></tr><tr><td>C09 Lo nuevo</td><td>IMG-09 pirámide RF</td><td>D11 vocabulario, D12 parámetros</td><td>E02 todo escrito</td><td>A04 principios</td><td>§6</td></tr><tr><td>C10 17 servicios</td><td>—</td><td>—</td><td>E07 ley no config</td><td><strong>A02</strong> servicios</td><td>§5</td></tr><tr><td>C11 Migración olas</td><td><strong>IMG-21</strong>, <strong>IMG-22</strong></td><td>D14</td><td>—</td><td>—</td><td>§8.1</td></tr><tr><td>C12 Checklist</td><td>IMG-25 (parcial)</td><td>D14</td><td>E12 medir antes</td><td>—</td><td>§12</td></tr><tr><td>C13 Menú 9 pestañas</td><td>IMG-06 números</td><td>—</td><td>—</td><td>—</td><td>§3 completo</td></tr><tr><td>C14 Permisos</td><td>IMG-17 seguridad (parcial)</td><td>—</td><td>—</td><td>—</td><td>§2.1</td></tr><tr><td>C15 Integraciones</td><td>IMG-16 arquitectura</td><td>D06 datos (API)</td><td><strong>E11</strong> datos coop</td><td>—</td><td>§9</td></tr><tr><td>C16 Contador</td><td>—</td><td>—</td><td>E06 nada se borra</td><td>F-M06, F-M15</td><td>§10</td></tr><tr><td>C17 Compras</td><td>—</td><td>—</td><td>—</td><td>F-M12</td><td>§3.8</td></tr><tr><td>C18 Sueldos</td><td>—</td><td>—</td><td>—</td><td>F-M16</td><td>§3.10</td></tr><tr><td>C19 FAQ</td><td>IMG-20 decisiones</td><td>—</td><td>—</td><td>—</td><td>§11</td></tr><tr><td>C20 Qué no copiamos</td><td>IMG-16</td><td>D04 nube, D05 servidores</td><td><strong>E10</strong> sin servidores</td><td>—</td><td>§7</td></tr><tr><td>C21 Números RF</td><td>IMG-11</td><td>—</td><td><strong>E02</strong>, E03 pruebas</td><td>—</td><td>§0.4</td></tr><tr><td>C22 Mapa 19+12</td><td>IMG-10</td><td>—</td><td>—</td><td>A01</td><td>§4, §4.1</td></tr><tr><td>C23 Por rol</td><td>—</td><td>—</td><td>—</td><td><code>roles-y-modulos</code></td><td>§1.1 + roles doc</td></tr><tr><td>C24 Anexo 120 PC</td><td>—</td><td>—</td><td>—</td><td>—</td><td>comparativo §3</td></tr></tbody></table><p><strong>Conflictos resueltos (acordar con marketing):</strong></p><table tabindex="0"><thead><tr><th>Tema</th><th>Decisión en guion unificado</th></tr></thead><tbody><tr><td>Diapositiva 8 documento base (IMG-08)</td><td><strong>No usar</strong>; usar <strong>IMG-D02 + D03</strong> (+ opcional D04–D10)</td></tr><tr><td>“119/120” vs “100 % cobertura” IMG-12</td><td>Mismo hecho: IMG-12 habla de entregables; <strong>IMG-C03</strong> del menú ProCoop. En voz: “del menú relevado, 119 de 120”.</td></tr><tr><td>API terceros</td><td><strong>IMG-D06</strong> y <strong>IMG-C15</strong> en ámbar hasta O11; complemento <strong>IMG-AP03</strong> si hay bloque técnico</td></tr><tr><td>Lo esencial IMG-E</td><td>Máximo <strong>3–4</strong> imágenes por reunión (E01, E04, E09, E12) para no repetir bloques</td></tr></tbody></table><hr><h2 id="_1-tres-versiones-de-la-presentacion" tabindex="-1">1. Tres versiones de la presentación <a class="header-anchor" href="#_1-tres-versiones-de-la-presentacion" aria-label="Permalink to &quot;1. Tres versiones de la presentación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Versión</th><th>Slides</th><th>Duración</th><th>Audiencia</th><th>Qué omitir</th></tr></thead><tbody><tr><td><strong>Corta</strong></td><td>12 (IMG-C01–C12)</td><td>20–25 min</td><td>Consejo con poco tiempo</td><td>Detalle menú por pestaña</td></tr><tr><td><strong>Estándar</strong></td><td>18 (+ C13–C18)</td><td>40–50 min</td><td>Gerencia + jefes de área</td><td>Tabla PC ítem por ítem</td></tr><tr><td><strong>Completa</strong></td><td>24 (+ C19–C24)</td><td>60–90 min</td><td>Comité de proyecto + TI</td><td>Llevar comparativo completo como anexo</td></tr></tbody></table><p>En las tres versiones, cerrar con <strong>checklist §12</strong> del comparativo (slide <strong>IMG-C12</strong>). Si la reunión sigue el <strong>guion unificado §0.5</strong>, C12 va después de IMG-D14 e IMG-22.</p><p><strong>Solo comparativo (sin documento base):</strong> usar §1 versión Corta = IMG-C01…C12 en orden.</p><hr><h2 id="_2-guion-slide-por-slide-tres-capas" tabindex="-1">2. Guión slide por slide (tres capas) <a class="header-anchor" href="#_2-guion-slide-por-slide-tres-capas" aria-label="Permalink to &quot;2. Guión slide por slide (tres capas)&quot;">​</a></h2><p>Convención: <strong>IMG-Cnn</strong> = código para pedir imagen o slide.</p><hr><h3 id="img-c01-—-portada" tabindex="-1">IMG-C01 — Portada <a class="header-anchor" href="#img-c01-—-portada" aria-label="Permalink to &quot;IMG-C01 — Portada&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> CoopApps y su cooperativa: mismo negocio, nueva plataforma. <strong>Subtítulo:</strong> Comparativo funcional respecto de ProCoop.</td></tr><tr><td><strong>Gerencia</strong></td><td>Enmarcar: no es “tirar ProCoop”, es <strong>evolucionar sin huecos</strong> con plan de olas.</td></tr><tr><td><strong>Respaldo</strong></td><td>DEC-007; comparativo §1; documento base §2.</td></tr></tbody></table><p><strong>Frase oral:</strong> “Les mostramos qué tienen hoy, qué propone CoopApps y cómo se pasa sin frenar la operación.”</p><hr><h3 id="img-c02-—-respeto-por-lo-que-tienen-hoy" tabindex="-1">IMG-C02 — Respeto por lo que tienen hoy <a class="header-anchor" href="#img-c02-—-respeto-por-lo-que-tienen-hoy" aria-label="Permalink to &quot;IMG-C02 — Respeto por lo que tienen hoy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> ProCoop hace mucho. Y lo hace bien. <strong>Viñetas:</strong> Facturación masiva · Multiservicio · Mora, compras, sueldos · Confianza de años.</td></tr><tr><td><strong>Gerencia</strong></td><td>Evita batalla ideológica; abre puerta a “¿qué mejora el modelo?”</td></tr><tr><td><strong>Respaldo</strong></td><td>DEMO ~12.500 comprobantes/mes; comparativo §1.3; dolores §1.4.</td></tr></tbody></table><p><strong>Frase oral:</strong> “No venimos a desmentir su sistema actual: venimos a quitarle fricción al modelo.”</p><hr><h3 id="img-c03-—-la-promesa-en-una-slide" tabindex="-1">IMG-C03 — La promesa en una slide <a class="header-anchor" href="#img-c03-—-la-promesa-en-una-slide" aria-label="Permalink to &quot;IMG-C03 — La promesa en una slide&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> Lo que ProCoop hace hoy → cubierto en CoopApps. <strong>Número grande:</strong> <strong>119 de 120</strong> funciones del menú relevado con destino. <strong>Pie:</strong> La restante es administrar la base de datos: en la nube lo hace la plataforma.</td></tr><tr><td><strong>Gerencia</strong></td><td>Mensaje de <strong>continuidad operativa</strong>; el riesgo “perdemos un módulo” queda acotado.</td></tr><tr><td><strong>Respaldo</strong></td><td>T03 §22: 112 absorbidas, 7 reemplazadas, 1 descartada, 0 sin destino — comparativo §0.3, §3.</td></tr></tbody></table><hr><h3 id="img-c04-—-ocho-aplicaciones-un-solo-dato" tabindex="-1">IMG-C04 — Ocho aplicaciones, un solo dato <a class="header-anchor" href="#img-c04-—-ocho-aplicaciones-un-solo-dato" aria-label="Permalink to &quot;IMG-C04 — Ocho aplicaciones, un solo dato&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> Una cooperativa, ocho formas de trabajar. <strong>Lista corta:</strong> Gestión web · App del socio (su marca) · Campo sin señal · Empleados · Sitio público · Tótem · (Plataforma) · Datos para integraciones.</td></tr><tr><td><strong>Gerencia</strong></td><td>Argumento <strong>integral</strong>: conviene migrar el ecosistema, no solo facturación.</td></tr><tr><td><strong>Respaldo</strong></td><td>Comparativo §0.2, §8; alcance §7 aplicaciones.</td></tr></tbody></table><p><strong>Visual sugerido:</strong> círculo central “Una sola información” y 8 íconos alrededor.</p><hr><h3 id="img-c05-—-el-socio-historia-simple" tabindex="-1">IMG-C05 — El socio (historia simple) <a class="header-anchor" href="#img-c05-—-el-socio-historia-simple" aria-label="Permalink to &quot;IMG-C05 — El socio (historia simple)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> El socio ve lo mismo que ve caja. <strong>Antes:</strong> portal sobre copia sincronizada. <strong>Después:</strong> contratar, pagar, reclamar y dar de baja desde el celular con <strong>marca de la cooperativa</strong>.</td></tr><tr><td><strong>Gerencia</strong></td><td>Menos reclamos por “en la web dice otra cosa”; más cobranza digital.</td></tr><tr><td><strong>Respaldo</strong></td><td>Comparativo §2.2, §6.4; dolores D4, D5; M19.</td></tr></tbody></table><p><strong>Frase oral:</strong> “Hoy muchas veces el portal va ‘detrás’ de la oficina. CoopApps unifica el dato.”</p><hr><h3 id="img-c06-—-dolores-que-ya-tienen-respuesta-escrita-7" tabindex="-1">IMG-C06 — Dolores que ya tienen respuesta escrita (7) <a class="header-anchor" href="#img-c06-—-dolores-que-ya-tienen-respuesta-escrita-7" aria-label="Permalink to &quot;IMG-C06 — Dolores que ya tienen respuesta escrita (7)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> Siete dolores, siete respuestas en especificación. <strong>Viñetas:</strong> Nube · Sin servidores propios · API de sus datos (plan) · App del socio · Su marca · Seguridad verificable · Soporte con caso y registro.</td></tr><tr><td><strong>Gerencia</strong></td><td>Conecta con pedidos del primer relevamiento; muestra <strong>trabajo hecho</strong>.</td></tr><tr><td><strong>Respaldo</strong></td><td><code>dolores-procoop-antes-y-despues.md</code> §1.1 tabla D1–D7; comparativo §2.</td></tr></tbody></table><p><strong>Nota presentador (honestidad):</strong> API completa en <strong>O11</strong>; antes, exportaciones y reportes (viñeta ámbar si preguntan).</p><hr><h3 id="img-c07-—-facturacion-y-cobranza-gerencia-operativa" tabindex="-1">IMG-C07 — Facturación y cobranza (gerencia operativa) <a class="header-anchor" href="#img-c07-—-facturacion-y-cobranza-gerencia-operativa" aria-label="Permalink to &quot;IMG-C07 — Facturación y cobranza (gerencia operativa)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> Facturar y cobrar con control. <strong>Viñetas:</strong> Lotes con excepciones visibles · Un solo cálculo de intereses · Pago confirmado antes de reconectar · Sin guardar números de tarjeta.</td></tr><tr><td><strong>Gerencia</strong></td><td>Menos riesgo fiscal y de cobro duplicado; mejor recupero de mora.</td></tr><tr><td><strong>Respaldo</strong></td><td>M05, M07, M08; comparativo §3.4–3.6, §10.</td></tr></tbody></table><hr><h3 id="img-c08-—-tecnica-y-campo-historia" tabindex="-1">IMG-C08 — Técnica y campo (historia) <a class="header-anchor" href="#img-c08-—-tecnica-y-campo-historia" aria-label="Permalink to &quot;IMG-C08 — Técnica y campo (historia)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> Del turno a la conformidad, en un solo flujo. <strong>Viñetas:</strong> Factibilidad · Visita con estado visible · Una app para técnico, lecturista y cobrador · Equipos rastreados por serie.</td></tr><tr><td><strong>Gerencia</strong></td><td>Primera impresión del socio; menos visitas fallidas sin registro.</td></tr><tr><td><strong>Respaldo</strong></td><td>M10, M13; dolores D13; comparativo §3.7, §6.1 ítems 2–3.</td></tr></tbody></table><hr><h3 id="img-c09-—-lo-nuevo-que-vende-el-cambio-no-esta-en-el-menu" tabindex="-1">IMG-C09 — Lo nuevo que vende el cambio (no está en el menú) <a class="header-anchor" href="#img-c09-—-lo-nuevo-que-vende-el-cambio-no-esta-en-el-menu" aria-label="Permalink to &quot;IMG-C09 — Lo nuevo que vende el cambio (no está en el menú)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> Lo que suma, más allá de “reemplazar pantallas”. <strong>Viñetas:</strong> Institucional y asambleas · Comunidad y avisos por zona · Diccionario propio (socio/asociado) · Expediente digital · Indicadores que coinciden en todo canal.</td></tr><tr><td><strong>Gerencia</strong></td><td>Justifica inversión <strong>a 10 años</strong>, no solo equivalencia.</td></tr><tr><td><strong>Respaldo</strong></td><td>Comparativo §6.1–6.3, M17, T09, T11; lista 49 ítems §6.</td></tr></tbody></table><hr><h3 id="img-c10-—-diecisiete-servicios-reglas-propias" tabindex="-1">IMG-C10 — Diecisiete servicios, reglas propias <a class="header-anchor" href="#img-c10-—-diecisiete-servicios-reglas-propias" aria-label="Permalink to &quot;IMG-C10 — Diecisiete servicios, reglas propias&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> Electricidad, gas, agua… y también sepelio, cementerio, vivienda. <strong>Mensaje:</strong> Cada servicio con sus reglas; la ley no se “apaga” con un parámetro.</td></tr><tr><td><strong>Gerencia</strong></td><td>Multiservicio sin parches; protecciones electrodependientes, mínimo vital, etc.</td></tr><tr><td><strong>Respaldo</strong></td><td>Comparativo §5, §10 casos difíciles; T12; alcance §3.</td></tr></tbody></table><p><strong>Frase oral:</strong> “No es un abono genérico: cada familia de servicio tiene su ficha.”</p><hr><h3 id="img-c11-—-migracion-sin-apagar-un-viernes" tabindex="-1">IMG-C11 — Migración sin apagar un viernes <a class="header-anchor" href="#img-c11-—-migracion-sin-apagar-un-viernes" aria-label="Permalink to &quot;IMG-C11 — Migración sin apagar un viernes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> Cambio por etapas. <strong>Viñetas:</strong> Convivencia con ProCoop · Comparar factura a factura · Dos ciclos conciliados · Códigos de barras antiguos aún válidos en transición.</td></tr><tr><td><strong>Gerencia</strong></td><td>Reduce miedo del consejo; explicita <strong>cuándo</strong> se apaga ProCoop.</td></tr><tr><td><strong>Respaldo</strong></td><td>T07; comparativo §8.1 tabla O0–O11; DEC-089 corte comercial O7, administrativo O11.</td></tr></tbody></table><p><strong>Número para slide:</strong> <strong>12 olas</strong> (O0–O11), <strong>172</strong> prompts de construcción (plan §1).</p><hr><h3 id="img-c12-—-cierre-y-checklist" tabindex="-1">IMG-C12 — Cierre y checklist <a class="header-anchor" href="#img-c12-—-cierre-y-checklist" aria-label="Permalink to &quot;IMG-C12 — Cierre y checklist&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Público</strong></td><td><strong>Título:</strong> ¿Qué pueden validar hoy? <strong>Checklist 6 ítems:</strong> Menú cubierto · Multiservicio · Socio paga y reclama · Mora con norma · Migración por etapas · Datos exportables.</td></tr><tr><td><strong>Gerencia</strong></td><td>Llamado a <strong>decisión</strong>: validar piloto, prioridades, fecha de paralelo.</td></tr><tr><td><strong>Respaldo</strong></td><td>Comparativo §12 completo (12 ítems); comparativo §14 frase cierre.</td></tr></tbody></table><hr><h3 id="slides-opcionales-presentacion-estandar-completa" tabindex="-1">Slides opcionales (presentación estándar / completa) <a class="header-anchor" href="#slides-opcionales-presentacion-estandar-completa" aria-label="Permalink to &quot;Slides opcionales (presentación estándar / completa)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Código</th><th>Título público</th><th>Gerencia</th><th>Respaldo comparativo</th></tr></thead><tbody><tr><td><strong>IMG-C13</strong></td><td>Las 9 pestañas de hoy, reordenadas</td><td>Curva de adopción: búsqueda “como en ProCoop” (T03)</td><td>§3 por pestaña</td></tr><tr><td><strong>IMG-C14</strong></td><td>Permisos: menos “usuario Dios”</td><td>40 roles plantilla; separación de funciones</td><td>§2.1, T02</td></tr><tr><td><strong>IMG-C15</strong></td><td>Integraciones bajo control</td><td>Bóveda de credenciales; reintentos sin duplicar</td><td>§9</td></tr><tr><td><strong>IMG-C16</strong></td><td>Contador y auditoría tranquilos</td><td>Nada se borra; libro IVA; auditoría encadenada</td><td>§10, M06, M15</td></tr><tr><td><strong>IMG-C17</strong></td><td>Compras y proveedores</td><td>Anti-fraude CBU; tres vías</td><td>§3.8, M12</td></tr><tr><td><strong>IMG-C18</strong></td><td>Personal y sueldos</td><td>Libro sueldo digital; dos meses en paralelo</td><td>§3.10, M16, O9</td></tr><tr><td><strong>IMG-C19</strong></td><td>Preguntas que van a hacer</td><td>FAQ preparada</td><td>§11</td></tr><tr><td><strong>IMG-C20</strong></td><td>Qué no copiamos tal cual (y por qué)</td><td>Escritorio → web; réplica → dato único</td><td>§7</td></tr><tr><td><strong>IMG-C21</strong></td><td>Números de la especificación</td><td>Profundidad del trabajo ya hecho</td><td>§0.4: 4.213 RF, 293 RNF, 31 anexos</td></tr><tr><td><strong>IMG-C22</strong></td><td>Mapa mental 19 + 12 módulos</td><td>Dónde vive cada área</td><td>§4, §4.1 DFA 29</td></tr><tr><td><strong>IMG-C23</strong></td><td>Por rol: qué gana cada uno</td><td>Matriz consejo/gerencia/áreas</td><td>§1.1 + <code>roles-y-modulos-para-claude.md</code></td></tr><tr><td><strong>IMG-C24</strong></td><td>Anexo: 120 funciones</td><td>“Si dudan de un ítem del menú, está en el PDF”</td><td>Comparativo §3 completo</td></tr></tbody></table><hr><h2 id="_3-matriz-mensaje-marketing-↔-respaldo-gerencial-tecnico" tabindex="-1">3. Matriz “mensaje marketing ↔ respaldo gerencial/técnico” <a class="header-anchor" href="#_3-matriz-mensaje-marketing-↔-respaldo-gerencial-tecnico" aria-label="Permalink to &quot;3. Matriz “mensaje marketing ↔ respaldo gerencial/técnico”&quot;">​</a></h2><p>Para copy de folletos, mail o landing <strong>sin contradecir</strong> a sistemas.</p><table tabindex="0"><thead><tr><th>Mensaje marketing (permitido)</th><th>Condición / matiz gerencial</th><th>Respaldo técnico (una línea)</th></tr></thead><tbody><tr><td>“Cubrimos el ProCoop que usan”</td><td>Mismo <strong>negocio</strong>, no mismas pantallas</td><td>PC-001…120 → SM-* (T03 §22)</td></tr><tr><td>“App del socio a su medida”</td><td>Requiere publicar marca (T03, M19)</td><td>RF-POR marca, PWAs por tenant</td></tr><tr><td>“En la nube, sin servidores”</td><td>SaaS; backup del proveedor + exportación propia</td><td>T01 RF-PLA-119, exportación tenant</td></tr><tr><td>“Facturación masiva segura”</td><td>Piloto debe validar volumen real</td><td>RNF capacidad 50k suministros/60 min (T08)</td></tr><tr><td>“Integrado con ARCA, bancos, SIRO…”</td><td>Cada cooperativa habilita fichas</td><td>T06 115 fichas; modo prueba/producción</td></tr><tr><td>“Inteligencia artificial que ayuda”</td><td>No ejecuta cobros/cortes solo</td><td>Principio IA asiste; M09, M04, M12</td></tr><tr><td>“Open API para la cooperativa”</td><td><strong>O11</strong> (adelanto RO solo lectura: decisión)</td><td>T10 RF-BIA API ext; dolores §2.3</td></tr><tr><td>“Institucional completo”</td><td>Ola <strong>O10</strong>; mínimo antes en O2/O4</td><td>M17 anexo</td></tr><tr><td>“Migración acompañada”</td><td>Piloto Laguna Larga; 2 ciclos paralelos</td><td>T07, DEC-088/089</td></tr></tbody></table><hr><h2 id="_4-discurso-por-perfil-30-segundos-cada-uno" tabindex="-1">4. Discurso por perfil (30 segundos cada uno) <a class="header-anchor" href="#_4-discurso-por-perfil-30-segundos-cada-uno" aria-label="Permalink to &quot;4. Discurso por perfil (30 segundos cada uno)&quot;">​</a></h2><p>Texto listo para notas del presentador o video corporativo.</p><table tabindex="0"><thead><tr><th>Perfil</th><th>Texto</th></tr></thead><tbody><tr><td><strong>Socio (comunicación externa)</strong></td><td>“Va a tener la cooperativa en el celular con su nombre y sus colores: misma deuda, mismas facturas y mismos trámites que en ventanilla, sin esperar a que se sincronice un portal aparte.”</td></tr><tr><td><strong>Presidente / consejo</strong></td><td>“No le quitamos funciones al menú que ya conocen: 119 de 120 están cubiertas. El cambio es por etapas, con dos facturaciones comparadas antes de apagar el sistema viejo, y sus datos se pueden exportar si algún día lo necesitan.”</td></tr><tr><td><strong>Gerente general</strong></td><td>“Un solo dato para oficina, campo y portal; indicadores que no discuten entre sí; y reglas escritas para los casos difíciles —mora, electrodependientes, multiservicio— que hoy viven en parámetros que pocos dominan.”</td></tr><tr><td><strong>Jefe de sistemas</strong></td><td>“Desaparece el Agente y la réplica MySQL de CoopOnline: el portal consume el mismo backend que la gestión. Integraciones con bóveda, idempotencia en cobros y FE, y mapa PC→SM para no perder trazabilidad en la migración.”</td></tr><tr><td><strong>Marketing interno</strong></td><td>“Por fin pueden comunicar con marca propia: landing, app instalable, avisos por barrio cuando hay un corte, encuestas y NPS —sin pedir desarrollo a medida cada vez.”</td></tr></tbody></table><hr><h2 id="_5-objeciones-frecuentes-—-respuesta-en-tres-capas" tabindex="-1">5. Objeciones frecuentes — respuesta en tres capas <a class="header-anchor" href="#_5-objeciones-frecuentes-—-respuesta-en-tres-capas" aria-label="Permalink to &quot;5. Objeciones frecuentes — respuesta en tres capas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Objeción (público)</th><th>Respuesta corta (slide)</th><th>Gerencia</th><th>Respaldo</th></tr></thead><tbody><tr><td>“¿Perdemos funciones?”</td><td><strong>119/120</strong> del menú relevado.</td><td>Pedir lista de 5 funciones críticas propias y cruzar con §3.</td><td>Comparativo §3, §12 ítem 1</td></tr><tr><td>“El portal ya existe”</td><td>Sí: <strong>CoopOnline</strong>. Mejora: <strong>mismo dato</strong> que caja.</td><td>Medir reclamos “web distinta a oficina”.</td><td>§2.2, integraciones fichas §14.1</td></tr><tr><td>“¿Y si el proveedor cierra?”</td><td>Exportación completa del tenant.</td><td>Cláusula contractual + prueba de export en piloto.</td><td>T01, T10; comparativo §11</td></tr><tr><td>“Es caro cambiar todo”</td><td>Cambio <strong>por olas</strong>; convivencia.</td><td>ROI: menos servidores, soporte, doble carga sync.</td><td>§8.1</td></tr><tr><td>“La API prometida”</td><td>Exportaciones ya; API <strong>O11</strong>.</td><td>Decidir adelanto read-only.</td><td>§6.3 nota; dolores §2.3</td></tr><tr><td>“Nuestros perfiles son distintos”</td><td><strong>40 roles</strong> plantilla ajustables.</td><td>Taller 1 día por área.</td><td>T02; roles-y-modulos</td></tr></tbody></table><hr><h2 id="_6-que-llevar-impreso-al-lado-del-marketing" tabindex="-1">6. Qué llevar impreso al lado del marketing <a class="header-anchor" href="#_6-que-llevar-impreso-al-lado-del-marketing" aria-label="Permalink to &quot;6. Qué llevar impreso al lado del marketing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Material</th><th>Para quién</th></tr></thead><tbody><tr><td><a href="./comparativo-funcional-procoop-vs-coopapps"><code>comparativo-funcional-procoop-vs-coopapps.md</code></a></td><td>Técnico / respaldo en Q&amp;A profunda</td></tr><tr><td><a href="./dolores-procoop-antes-y-despues"><code>dolores-procoop-antes-y-despues.md</code></a></td><td>Imágenes antes/después</td></tr><tr><td><a href="./alcance-especificacion-modulo-por-modulo"><code>alcance-especificacion-modulo-por-modulo.md</code></a></td><td>Gerencia por área</td></tr><tr><td>Este documento</td><td>Marketing y guion</td></tr></tbody></table><hr><h2 id="_7-actualizacion-cruzada" tabindex="-1">7. Actualización cruzada <a class="header-anchor" href="#_7-actualizacion-cruzada" aria-label="Permalink to &quot;7. Actualización cruzada&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Documento</th><th>Relación</th></tr></thead><tbody><tr><td>Comparativo v1.1</td><td>Fuente de verdad funcional</td></tr><tr><td><strong>Este archivo</strong></td><td>Capa comunicación + <strong>guion unificado §0.5</strong> + cruces §0.6</td></tr><tr><td><code>documento-base-presentacion.md</code></td><td>IMG-01…25; ver nota en §1.1 sobre IMG-08 y bloque IMG-C</td></tr><tr><td><code>dolores-procoop-antes-y-despues.md</code></td><td>IMG-D01…14; encaje en §0.5 filas 6–7 y 21</td></tr><tr><td><code>lo-esencial-para-imagenes.md</code></td><td>IMG-E01…12; usar con moderación (tabla §0.6)</td></tr><tr><td><code>alcance-especificacion-modulo-por-modulo.md</code></td><td>IMG-A01…08 tras bloque comparativo (§0.5 filas 12–15)</td></tr></tbody></table><p>Si el comparativo cambia de versión, actualizar <strong>IMG-C</strong>, la matriz §3 y la tabla <strong>§0.6</strong>.</p><hr><h2 id="_8-una-frase-para-marketing-pie-de-campana" tabindex="-1">8. Una frase para marketing (pie de campaña) <a class="header-anchor" href="#_8-una-frase-para-marketing-pie-de-campana" aria-label="Permalink to &quot;8. Una frase para marketing (pie de campaña)&quot;">​</a></h2><blockquote><p><strong>“Mismo negocio que ProCoop. Un solo dato para oficina, campo y socio. Su marca en el celular. Cambio por etapas, no de un día para otro.”</strong></p></blockquote><p><em>(Condiciones: no usar “API completa desde el día 1”; no decir “mismas pantallas”.)</em></p>`,105)])])}const g=a(r,[["render",s]]);export{m as __pageData,g as default};
